  'Anne için: kimlik, gebelik kartı ve tahliller, önden açılan gecelik, emzirme sütyeni, lohusa pedi, terlik, şarj aleti.': 'Для мамы: документы, обменная карта и анализы, ночная рубашка с застёжкой спереди, бюстгальтер для кормления, послеродовые прокладки, тапочки, зарядка.',
