  'Anne sütü alan bebekler bazen birkaç gün kaka yapmayabilir; yumuşaksa genellikle normaldir.': 'Дети на грудном вскармливании иногда несколько дней не какают; если стул мягкий, это обычно нормально.',
  'Anne sütü alan bebeklerin kakası doğal olarak yumuşak ve sıktır; bu ishal değildir.': 'У детей на грудном вскармливании стул естественно мягкий и частый; это не понос.',
  'Anne sütü prematüre bebekler için özellikle değerlidir.': 'Грудное молоко особенно ценно для недоношенных.',
  'Anne sütü veremeyen veya yetmeyen durumlarda formül mama güvenli bir alternatiftir; hazırlama kurallarına uyulmalıdır.': 'Когда грудное молоко невозможно или его недостаточно, смесь — безопасная альтернатива; правила приготовления нужно соблюдать.',
  'Anne sütüyle beslenen bebeklerde sarılık biraz daha uzun sürebilir.': 'У детей на грудном вскармливании желтуха может длиться немного дольше.',
  'Anne ve aile günlüğü': 'Дневник мамы и семьи',
  'Anne Ürünleri': 'Товары для мамы',
  'Anne, bebek ve aile yaşamı için güvenilir başlangıç bilgileri.': 'Надёжная базовая информация для жизни мамы, малыша и семьи.',
  'Anne, bebek ve kadın yaşamına dair her şey tek yerde.': 'Всё о материнстве, малышах и жизни женщины — в одном месте.',
  'Annelerin çoğunda ilk 2 hafta ağlama, duygusal dalgalanma görülebilir (doğum sonrası hüzün).': 'У большинства мам в первые 2 недели бывают плаксивость и перепады настроения (беби-блюз).',
  'Annelik': 'Материнство',
  'Annelik ve günlük yaşamın yükü kaygıyı artırabilir; kaygıyı tanımak ve yönetmek mümkündür.': 'Нагрузка материнства и повседневной жизни может усиливать тревогу; её можно распознать и справиться с ней.',
  'Annenden, kayınvalidenden öğrendiğin tarifleri “Tarif ekle” ile yaz. Tarif detaylarındaki “Aile tarif defterime ekle” ile hazır tarifleri de buraya kaydedebilirsin.': 'Записывайте кнопкой «Добавить рецепт» рецепты, которым научили вас мама или свекровь. Готовые рецепты можно сохранить сюда кнопкой «Добавить в мою семейную книгу рецептов» на странице рецепта.',
  'Annenin uykusu': 'Сон мамы',
  'Antibiyotik gerekiyorsa hekim reçetesiyle kullanılmalıdır.': 'Если нужны антибиотики, их принимают по назначению врача.',
  'Antibiyotikler virüslere etki etmez; yalnızca doktor önerisiyle kullanılmalıdır.': 'Антибиотики не действуют на вирусы; их следует применять только по назначению врача.',
