  'Aşı kartını ve uygulamadaki aşı takvimini güncel tut.': 'Ведите прививочный сертификат и календарь прививок в приложении.',
  'Aşı kayıtları': 'Записи о прививках',
  'Aşı kayıtlarım': 'Мои записи о прививках',
  'Aşı kayıtlarını bebeğin sağlık günlüğünde, resmî aşı takvimini ise çocuk profilinde görebilirsin. Aşı zamanlaması için her zaman doktorunun ve Sağlık Bakanlığı takviminin önerisini esas al.': 'Записи о прививках можно посмотреть в дневнике здоровья малыша, а официальный календарь — в профиле ребёнка. Сроки прививок всегда сверяйте с врачом и органами здравоохранения.',
  'Aşı rehberi': 'Гид по прививкам',
  'Aşı sonrası 3 saatten uzun teselli edilemeyen ağlama, havale veya yüksek ateş.': 'Безутешный плач дольше 3 часов, судороги или высокая температура после прививки.',
  'Aşı sonrası beklenmeyen veya ağır belirtilerde sağlık kuruluşundan destek alın.': 'При неожиданных или тяжёлых симптомах после прививки обратитесь в медицинское учреждение.',
  'Aşı sonrası emzirmek ve kucaklamak bebeği rahatlatır.': 'Грудь и объятия успокаивают малыша после прививки.',
  'Aşı sonrası hafif ateş, huzursuzluk ve aşı yerinde kızarıklık olağandır, 1–2 günde geçer.': 'Небольшая температура, капризность и покраснение в месте укола после прививки нормальны и проходят за 1–2 дня.',
  'Aşı uygulamalarını çocuğun resmi aşı kartına göre doğrulayın; bu uygulamadaki notlar resmi kayıt değildir.': 'Сверяйте прививки с официальным прививочным сертификатом ребёнка; записи в приложении не являются официальными.',
