  'Bebek ağlıyor, başını çeviriyor veya geriliyorsa ara vermek gerekir.': 'Если малыш плачет, отворачивается или напрягается, сделайте паузу.',
  'Bebek bakımı': 'Уход за малышом',
  'Bebek bakımı sırasında uyku bölünmesi kaçınılmazdır; ama uzun süreli uykusuzluk ruh sağlığını etkiler.': 'Прерывистый сон неизбежен при уходе за малышом, но длительный недосып влияет на психическое здоровье.',
  'Bebek bakımı, büyüme, adet ve gebelik kayıtları cihazın güvenli deposunda şifrelenir.': 'Записи об уходе, росте, менструациях и беременности шифруются в защищённом хранилище устройства.',
  'Bebek bakımı, gebelik, yemek planlama veya uygulamanın kullanımı hakkında genel bir soru sorabilirsiniz.': 'Можно задать общий вопрос об уходе за малышом, беременности, планировании питания или работе приложения.',
  'Bebek banyosu': 'Купание малыша',
  'Bebek başını sürekli aynı tarafa çeviriyor ve diğer tarafa dönemiyorsa.': 'Если малыш всегда поворачивает голову в одну сторону и не может повернуть в другую.',
