  'Bebek bütçesi': 'Бюджет на малыша',
  'Bebek bütçesini ve ihtiyaç listesini uygulamadaki alışveriş bölümünde hazırla.': 'Составьте бюджет и список необходимого для малыша в разделе покупок приложения.',
  'Bebek cildi ve döküntüler': 'Кожа малыша и сыпь',
  'Bebek dik otururken ve gözetim altında besle.': 'Кормите малыша сидя прямо и под присмотром.',
  'Bebek ekle': 'Добавить малыша',
