  'Bebek gelince çift ilişkisi de değişir; açık iletişim ve adil iş bölümü yükü hafifletir.': 'С появлением малыша меняются и отношения пары; открытое общение и справедливое распределение дел облегчают нагрузку.',
  'Bebek gelişimi ve kayıtları': 'Развитие и записи малыша',
  'Bebek hareketleri': 'Шевеления малыша',
  'Bebek hareketlerinde azalma.': 'Уменьшение шевелений.',
  'Bebek hareketlerinde belirgin azalma (son aylarda).': 'Заметное уменьшение шевелений (в последние месяцы).',
  'Bebek hareketlerinde belirgin azalma veya durma: hemen başvur.': 'Заметное уменьшение или прекращение шевелений: сразу обратитесь к врачу.',
  'Bebek hareketlerinde belirgin azalma, kanama, su gelmesi, düzenli kasılmalar, şiddetli baş ağrısı veya görme bozukluğu: aynı gün başvur. Acil durumda 112.': 'Заметное уменьшение шевелений, кровотечение, подтекание жидкости, регулярные схватки, сильная головная боль или нарушения зрения: обратитесь к врачу в тот же день. В экстренном случае звоните по местному номеру экстренной помощи.',
  'Bebek hareketlerini say (10 hareket)': 'Считать шевеления малыша (10 движений)',
  'Bebek havlusu': 'Детское полотенце',
  'Bebek her uykuda sırtüstü yatırılmalıdır; yan veya yüzüstü yatış önerilmez.': 'Укладывайте малыша на спину при каждом сне; на боку или на животе не рекомендуется.',
  'Bebek hızla büyüdüğü için kıyafet ve ekipmanlar kısa süre kullanılır.': 'Малыши быстро растут, поэтому одежда и вещи используются недолго.',
  'Bebek hızla kilo alır; doğuma hazırlık ve bebek hareketlerinin takibi önem kazanır.': 'Малыш быстро набирает вес; подготовка к родам и наблюдение за шевелениями становятся важными.',
  'Bebek inince nefes rahatlar ama idrar sıklığı artar.': 'Когда малыш опускается, дышать легче, но мочиться приходится чаще.',
  'Bebek isimleri': 'Имена для малыша',
  'Bebek istedikçe, günde en az 8–12 kez emzir.': 'Кормите по требованию, не реже 8–12 раз в сутки.',
  'Bebek için: 2–3 takım zıbın ve tulum, şapka, çorap, battaniye, yenidoğan bezi.': 'Для малыша: 2–3 комплекта распашонок и слипов, шапочка, носочки, плед, подгузники для новорождённых.',
  'Bebek kaşığı': 'Детская ложка',
