  'Bebek mutlu, kilo alıyor ve rahat nefes alıyorsa genellikle tedavi gerekmez.': 'Если малыш доволен, прибавляет в весе и спокойно дышит, лечение обычно не нужно.',
  'Bebek odası ve güvenli uyku alanını planla.': 'Продумайте детскую и безопасное место для сна.',
