  'Eksik içerik': 'Недостающий материал',
  'Eksik malzeme: {0}': 'Не хватает ингредиента: {0}',
  'Eksikleri alışveriş listesine ekle': 'Добавить недостающее в список покупок',
  'Eksikleri otomatik seç': 'Автоматически выбрать недостающее',
  'Eksiklerin kategori dağılımı:': 'Недостающее по категориям:',
  'Ekşimsi elmalar (Granny Smith) daha dengeli bir tat verir.': 'Кислые яблоки (Гренни Смит) дают более сбалансированный вкус.',
  'El kavrama refleksi gelişir; saçlar uzar.': 'Развивается хватательный рефлекс; волосы становятся длиннее.',
  'El kremi': 'Крем для рук',
  'El sallayarak selamlaşmayı canlandırın.': 'Изобразите приветствие, помахав рукой.',
  'El ve tırnak bakımı': 'Уход за руками и ногтями',
  'El yıkama, diş fırçalama ve günlük öz bakım rutinlerini birlikte uygulayın. Tuvalet alışkanlığında hazır oluşa saygı gösterin.': 'Мойте руки, чистите зубы и выполняйте ежедневный уход вместе. Уважайте готовность к горшку.',
