  'El, ayak ve burun gibi bölümleri adlandırın.': 'Называйте руку, ногу, нос и другие части тела.',
  'El-ayak-ağız hastalığı, suçiçeği, kızamıkçık, grip ve mide-bağırsak enfeksiyonları sık görülür.': 'Часто встречаются синдром «рука-нога-рот», ветрянка, розеола, грипп и кишечные инфекции.',
