  'Elektrik güvenliğinde profesyonel önerilere uyun.': 'По электробезопасности следуйте рекомендациям специалистов.',
  'Elektrik prizleri için koruma.': 'Защита для электрических розеток.',
  'Elektrik veya kimyasal yanık, nefes darlığı: 112.': 'Электрический или химический ожог, одышка: звоните по местному номеру экстренной помощи.',
  'Elif’in nuru': 'Свет Элиф',
  'Elleri sık yıka; hasta kişilerin bebeği öpmesine izin verme.': 'Чаще мойте руки; не позволяйте больным людям целовать малыша.',
  'Ellerini yıka; kaynatılıp 70 °C civarına soğutulmuş su kullan.': 'Вымойте руки; используйте прокипячённую и остывшую примерно до 70 °C воду.',
  'Elleriniz': 'Ваши руки',
  'Ellerinizi yıkadıktan sonra nemlendirin. Tırnakları temiz ve kısa tutun; keskin aletlerle tırnak etini zorlamayın.': 'Увлажняйте руки после мытья. Держите ногти чистыми и короткими; не травмируйте кутикулу острыми инструментами.',
  'Ellerinizle yumuşak ritimler oluşturun.': 'Создавайте руками мягкие ритмы.',
  'Ellerle keşif ve birlikte etkileşim': 'Исследовать руками и взаимодействовать вместе',
  'Elma ve tahini üzerine ekleyerek servis edin.': 'Добавьте сверху яблоко и тахини и подавайте.',
  'Elma; alımlı': 'Яблоко; привлекательная',
  'Elmaları doğrayıp tarçınla karıştırarak kaba alın.': 'Нарежьте яблоки, смешайте с корицей и выложите в форму.',
  'Elmaları küp doğrayıp tarçınla karıştırarak fırın kabına yayın.': 'Нарежьте яблоки кубиком, смешайте с корицей и разложите в форме.',
  'Elmaları küçük küpler halinde doğrayın': 'Нарежьте яблоки мелким кубиком',
  'Elmaları rendeleyip tarçınla harmanlayın.': 'Натрите яблоки и перемешайте с корицей.',
  'Elmaları rendeleyip tarçınla karıştırın.': 'Натрите яблоки и смешайте с корицей.',
  'Elmaları soyup dilimleyin; limon suyu, esmer şeker ve tarçınla karıştırıp fırın kabına yayın.': 'Очистите и нарежьте яблоки; смешайте с лимонным соком, коричневым сахаром и корицей и выложите в форму.',
  'Elmaları soyup küp doğrayın.': 'Очистите яблоки и нарежьте кубиком.',
  'Elmaları ve cevizleri ekleyip küçük fırın kabına dökün': 'Добавьте яблоки и орехи и вылейте в небольшую форму',
  'Elmalı cevizli yoğurt tatlısı': 'Йогуртовый десерт с яблоком и орехами',
  'Elmalı crumble': 'Яблочный крамбл',
  'Elmalı tarçınlı crumble': 'Яблочный крамбл с корицей',
  'Elmalı tarçınlı fırın yulaf': 'Запечённая овсянка с яблоком и корицей',
  'Elmalı tarçınlı kek': 'Яблочный кекс с корицей',
