  'Elmalı yoğurtlu kup': 'Стаканчики с йогуртом и яблоком',
  'Elmalı yulaf lapası': 'Овсяная каша с яблоком',
  'Elmayı ekleyip 3 dakika daha karıştırın.': 'Добавьте яблоко и помешивайте ещё 3 минуты.',
  'Elmayı küçük doğrayıp tavada 3-4 dakika yumuşatın ve soğutun.': 'Мелко нарежьте яблоко, потушите на сковороде 3-4 минуты и остудите.',
  'Elmayı rendeleyin ve diğer malzemelerle karıştırın.': 'Натрите яблоко и смешайте с остальными ингредиентами.',
  'Elmayı rendeleyin.': 'Натрите яблоко.',
  'Elmayı rendeleyip tarçınla karıştırın.': 'Натрите яблоко и смешайте с корицей.',
  'Elmayı yıkayıp rendeleyin.': 'Вымойте и натрите яблоко.',
  'Elçi kadın; ülkeyi temsil eden': 'Посланница; представляющая страну',
  'Embriyo dönemi sona erer, "fetüs" dönemi başlar; hayati organlar yerini almıştır.': 'Эмбриональный период заканчивается и начинается «плодный»; жизненно важные органы на месте.',
  'Emekleme ve tutunarak kalkma dönemi: priz kapakları, merdiven kapısı, köşe koruyucu, mobilyaları duvara sabitleme. Yürüteç kullanma.': 'Период ползания и вставания: заглушки на розетки, ворота на лестницу, накладки на углы, крепление мебели к стене. Не используйте ходунки.',
  'Emekler; tutunarak ayağa kalkmayı dener. Başparmak ve işaret parmağıyla küçük nesneleri tutmaya başlar. "baba", "mama" heceleri.': 'Ползает; пытается встать у опоры. Начинает брать мелкие предметы большим и указательным пальцами. Слоги «баба», «мама».',
  'Emicilik': 'Впитываемость',
  'Emmede isteksizlik, sürekli uyku hâli veya uyandırılamama.': 'Отказ от еды, постоянная сонливость или невозможность разбудить.',
