  'Küçük çocuklar sık düşer; çoğu düşme hafiftir ama bazı belirtiler acil değerlendirme gerektirir.': 'Маленькие дети часто падают; большинство падений неопасны, но некоторые признаки требуют срочного осмотра.',
  'Küçük çocuklarda yaralanmaların çoğu evde olur ve büyük kısmı önlenebilir.': 'Большинство травм у маленьких детей случаются дома, и большинство из них можно предотвратить.',
  'Küçük çocukların iştahı günden güne değişir; seçici yeme bu yaşlarda yaygındır.': 'Аппетит малышей меняется изо дня в день; избирательность в еде в этом возрасте обычна.',
