  'Kırıntıları elmaların üzerine dağıtın.': 'Рассыпьте крошку поверх яблок.',
  'Kırıntıları elmaların üzerine eşit serpin.': 'Равномерно посыпьте крошкой яблоки.',
  'Kısa da olsa ikinize ayırdığınız zamanlar planlayın.': 'Планируйте время только для вас двоих, пусть и недолгое.',
  'Kısa dinlenme araları planlayın; bakım sorumluluklarını paylaşın. Yorgunken bebeğinizle koltukta veya kanepede uyumamaya dikkat edin.': 'Планируйте короткие перерывы на отдых и делите уход. Когда устали, следите, чтобы не уснуть с малышом в кресле или на диване.',
  'Kısa hikâye kurma ve neden-sonuç soruları ekleyin.': 'Добавьте сочинение коротких историй и вопросы о причине и следствии.',
  'Kısa nefes egzersizleri ve fiziksel aktivite stres tepkisini azaltır.': 'Короткие дыхательные упражнения и физическая активность снижают реакцию на стресс.',
  'Kısa nefes molası': 'Короткая дыхательная пауза',
  'Kısa süre desteksiz oturabilir; sesin geldiği yöne döner. Hece tekrarları artar, ayna görüntüsüne ilgi gösterir.': 'Может недолго сидеть без опоры; поворачивается к источнику звука. Лепет усиливается; интересуется своим отражением.',
  'Kısa tekrarlar yapın; bebeğin bakışını ve tepkisini takip edin. Nesneleri ağzına götürmesine izin vermeyin.': 'Делайте короткие повторы; следите за взглядом и реакцией малыша. Не давайте тянуть предметы в рот.',
  'Kısa uyku. Bebeğin uyurken dinlenmeye, yardım istemeye çalış.': 'Мало сна. Старайтесь отдыхать, пока малыш спит, и просите о помощи.',
  'Kısa ve kararlı vedalaş; gizlice ayrılma.': 'Прощайтесь коротко и уверенно; не уходите тайком.',
  'Kısa şekerlemeler bile toparlanmaya yardımcı olur.': 'Даже короткий дневной сон помогает восстановиться.',
  'Kısa şekerlemeler bile yorgunluğu azaltır.': 'Даже короткий дневной сон уменьшает усталость.',
  'Kıskançlık sevginin değil, ilgiyi kaybetme korkusunun işaretidir.': 'Ревность — не признак нелюбви, а страх потерять внимание.',
  'Kısmi': 'Частично',
