  'Seyahatten önce gebelik kartını ve tahlil sonuçlarını yanına al.': 'Берите в поездку обменную карту и результаты анализов.',
  'Sezaryen büyük bir karın ameliyatıdır; iyileşme genellikle 6–8 hafta sürer.': 'Кесарево сечение — крупная полостная операция; восстановление обычно занимает 6–8 недель.',
  'Sezaryen sonrası ağır kaldırmaktan kaçın; öksürürken karnını yastıkla destekle.': 'После кесарева не поднимайте тяжёлое; при кашле придерживайте живот подушкой.',
  'Sezaryen sonrası emzirme mümkündür; yan yatarak veya koltuk altı pozisyonu rahat olabilir.': 'Кормить грудью после кесарева можно; удобными могут быть положение лёжа на боку или «из-под руки».',
  'Sezaryen sonrası iyileşme': 'Восстановление после кесарева сечения',
  'Sezaryen sonrası tam iyileşme 6–8 hafta sürebilir.': 'Полное восстановление после кесарева может занять 6–8 недель.',
  'Sezaryen tıbbi gerekliliklerde hayat kurtarıcıdır; büyük bir ameliyat olduğu için iyileşmesi daha uzundur.': 'Кесарево сечение спасает жизни, когда оно показано; как крупная операция, оно требует более долгого восстановления.',
  'Sezaryenden sonra da çoğu zaman mümkündür.': 'Часто это возможно и после кесарева сечения.',
  'Seçenek sun ("kırmızı mı mavi mi?") ve küçük görevler ver.': 'Предлагайте выбор («красный или синий?») и давайте маленькие поручения.',
  'Seçenek sunma ("elma mı muz mu?"), kutu içine şekil yerleştirme, birlikte toplama oyunu.': 'Предлагать выбор («яблоко или банан?»), сортеры, уборка вместе как игра.',
