  'Tatlılar': 'Десерты',
  'Tatlıyı ödül olarak kullanma; şekerli içecekleri sınırla.': 'Не используйте сладости как награду; ограничьте сладкие напитки.',
  'Tava kalabalık olursa balık kızarmaz, haşlanır; gerekirse iki partide pişirin.': 'Если сковорода переполнена, рыба тушится, а не жарится; при необходимости жарьте в два приёма.',
  'Tavada orta ateşte iki yüzünü kızartın; kalınlığına göre 12–18 dakika pişirin.': 'Обжарьте с двух сторон на среднем огне; готовьте 12–18 минут в зависимости от толщины.',
  'Tavada yağı ısıtıp tavuğu yüksek ateşte renk alana kadar çevirin.': 'Разогрейте масло и обжарьте курицу на сильном огне до румяности.',
  'Tavada zeytinyağıyla soğanı 3 dakika yumuşatın, salçayı ekleyip 1 dakika kavurun; rendelenmiş domatesi ve sıcak suyu ilave edip 3 dakika kaynatın.': 'Обжарьте лук на оливковом масле 3 минуты, добавьте томатную пасту на 1 минуту; добавьте тёртый помидор и горячую воду и кипятите 3 минуты.',
  'Tavuk 74°C iç sıcaklığa ulaşınca ocaktan alın.': 'Снимите с огня, когда курица прогреется до 74 °C.',
  'Tavuk bagetleri ve patatesleri yağ, kekik ve biberle harmanlayıp tepsiye tek kat dizin.': 'Перемешайте голени и картофель с маслом, тимьяном и паприкой и выложите в один слой.',
  'Tavuk iç sıcaklığı en az 74 °C olana dek yaklaşık 35–45 dakika pişirin.': 'Запекайте около 35–45 минут, пока температура внутри курицы не достигнет минимум 74 °C.',
  'Tavuk iç sıcaklığı en az 74 °C olana kadar yaklaşık 40–45 dakika pişirin.': 'Запекайте около 40–45 минут, пока температура внутри курицы не достигнет минимум 74 °C.',
  'Tavuk köftesi': 'Куриные котлеты',
  'Tavuk kıyması, kabak, yumurta ve galeta ununu yoğurup köfteler şekillendirin.': 'Вымесите куриный фарш, кабачок, яйцо и сухари и сформуйте котлеты.',
  'Tavuk kıyması, yumurta, galeta unu ve sebzeleri yoğurun.': 'Вымесите фарш, яйцо, сухари и овощи.',
  'Tavuk suyu, didiklenmiş tavuk ve nohudu ekleyin.': 'Добавьте куриный бульон, разобранную курицу и нут.',
  'Tavuk suyu, şehriye ve didiklenmiş tavuğu ekleyin': 'Добавьте куриный бульон, вермишель и разобранную курицу',
  'Tavuk suyunu, didiklenmiş tavuğu ve şehriyeyi ekleyin.': 'Добавьте куриный бульон, курицу и вермишель.',
  'Tavuk tamamen pişene kadar yaklaşık 20 dakika kısık ateşte pişirin.': 'Тушите на слабом огне около 20 минут до полной готовности курицы.',
  'Tavuk tamamen pişince dilimlenmiş mantarı ekleyin.': 'Когда курица будет готова, добавьте нарезанные грибы.',
  'Tavuk tamamen pişip içi pembe kalmayana kadar 40-45 dakika pişirin.': 'Запекайте 40-45 минут, пока курица не будет полностью готова и без розового внутри.',
  'Tavuk tamamen pişmiş olmalı; kemik bulunmamalı.': 'Курица должна быть полностью приготовлена; костей быть не должно.',
  'Tavuk ve biberleri şişlere dizip 200°C fırında yaklaşık 20–25 dakika pişirin.': 'Нанижите курицу и перец на шпажки и запекайте при 200 °C около 20–25 минут.',
  'Tavuk ve sebzeleri eşit büyüklükte doğrayın.': 'Нарежьте курицу и овощи одинаковыми кусочками.',
  'Tavuk ve sebzeleri güveç kabına alın; yağ ve suyu ekleyip karıştırın.': 'Сложите курицу и овощи в горшочек; добавьте масло и воду и перемешайте.',
