  'Telefon bildirimi isteğe bağlıdır ve izin gerektirir. Pil kısıtlamaları nedeniyle bildirim gecikebilir. Acil sağlık durumları veya ilaç takibi için tek başına kullanılmamalıdır.': 'Уведомления на телефоне необязательны и требуют разрешения. Из-за ограничений батареи они могут задерживаться. Не полагайтесь только на них в экстренных медицинских ситуациях или при приёме лекарств.',
