  'Temizlik ürünlerini çocuklardan uzak tutun.': 'Держите бытовую химию вдали от детей.',
  'Temmuz': 'Июль',
  'Ten tene temas bebeğin ısısını ve kalp atımını düzenler, emzirmeyi başlatmayı kolaylaştırır.': 'Контакт «кожа к коже» регулирует температуру и сердцебиение малыша и облегчает начало кормления.',
  'Ten tene temas, yüz yüze konuşma, ninni. Kısa süreli, uyanıkken gözetimli karın üstü zaman.': 'Контакт «кожа к коже», разговор лицом к лицу, колыбельные. Короткое выкладывание на живот под присмотром во время бодрствования.',
  'Tencerede salça, sebzeler, mercimek ve suyu birleştirin.': 'Соедините в кастрюле томатную пасту, овощи, чечевицу и воду.',
  'Tencerede tereyağını eritip unu 1 dakika kavurun; sütü çırparak ekleyin ve kaynayıp hafif koyulaşana kadar 4 dakika karıştırın.': 'Растопите масло, обжарьте муку 1 минуту; влейте молоко, взбивая, и мешайте 4 минуты до закипания и лёгкого загустения.',
  'Tencerede yağ ile havucu 3 dakika çevirin.': 'Обжарьте морковь в масле в кастрюле 3 минуты.',
  'Tencerede yağı ısıtıp soğan ve havucu 3 dakika çevirin.': 'Разогрейте масло и обжарьте лук с морковью 3 минуты.',
  'Tencereye dizip yarısına gelecek kadar su ekleyin; 35–40 dakika pişirin.': 'Уложите в кастрюлю, налейте воды до половины; тушите 35–40 минут.',
  'Tencereye kabak, şeker ve suyu alın.': 'Положите тыкву, сахар и воду в кастрюлю.',
  'Tencereye sebzeleri yerleştirip zeytinyağını ekleyin.': 'Сложите овощи в кастрюлю и добавьте оливковое масло.',
  'Tepside 20 dakika pişirip limonla servis edin.': 'Запекайте на противне 20 минут и подавайте с лимоном.',
  'Tepside 25-30 dakika yumuşayana kadar pişirin.': 'Запекайте на противне 25-30 минут до мягкости.',
  'Tepsiye dizip içlerine az yağ ve peynir koyun.': 'Выложите на противень и положите в каждый немного масла и сыра.',
  'Tepsiye tek kat yayıp 30 dakika, iki kez sallayarak çıtırlaşana kadar pişirin.': 'Выложите в один слой и запекайте 30 минут, дважды встряхнув, до хруста.',
  'Tepsiye üst üste gelmeyecek şekilde yayın.': 'Разложите на противне в один слой.',
  'Terbiyeli kereviz çorbası': 'Суп из сельдерея с яично-йогуртовой заправкой',
  'Terbiyeli sulu köfte': 'Суп с фрикадельками и яично-йогуртовой заправкой',
  'Terbiyeli tavuk çorbası': 'Куриный суп с яично-йогуртовой заправкой',
  'Terbiyeyi tencereye döküp karıştırarak kaynatın; nane ekleyin.': 'Влейте заправку в кастрюлю и, помешивая, доведите до кипения; добавьте мяту.',
  'Terbiyeyi tencereye karıştırarak dökün, birkaç dakika kaynatın.': 'Влейте заправку в кастрюлю, помешивая, и проварите несколько минут.',
  'Terbiyeyi tencereye karıştırarak dökün, hafifçe kaynatın; naneli tereyağı gezdirin.': 'Влейте заправку в кастрюлю, помешивая, дайте слегка закипеть; полейте маслом с мятой.',
  'Terbiyeyi tencereye karıştırarak ekleyip birkaç dakika daha ısıtın.': 'Влейте заправку в кастрюлю, помешивая, и прогрейте ещё несколько минут.',
  'Terbiyeyi yavaşça tencereye katın; kaynatmadan ısıtıp servis edin.': 'Медленно влейте заправку в кастрюлю; прогрейте, не доводя до кипения, и подавайте.',
  'Tercihler kaydedildi; telefon bildirimleri güncellenemedi.': 'Настройки сохранены; не удалось обновить уведомления на телефоне.',
  'Tercihler kaydedilemedi. Önceki tercihler korunuyor.': 'Не удалось сохранить настройки. Прежние настройки сохранены.',
  'Tercihler ve yapılacaklar': 'Настройки и дела',
  'Tercihlerini 1 sayfayı geçmeyecek şekilde yaz ve hekiminle konuş.': 'Изложите пожелания не более чем на 1 странице и обсудите с врачом.',
  'Tereyağı ve doğranmış çikolatayı ekleyip eriyene kadar karıştırın.': 'Добавьте масло и рубленый шоколад и мешайте до растворения.',
  'Tereyağı ve unu kavurup sütü azar azar ekleyerek koyu sos hazırlayın.': 'Обжарьте масло с мукой и, постепенно добавляя молоко, приготовьте густой соус.',
  'Tereyağı, un ve sütle beşamel sos hazırlayın.': 'Приготовьте соус бешамель из масла, муки и молока.',
  'Tereyağında pirinci 2 dakika kavurun.': 'Обжарьте рис на сливочном масле 2 минуты.',
  'Tereyağında pirinci birkaç dakika kavurun.': 'Обжарьте рис на сливочном масле несколько минут.',
  'Tereyağında soğan ve mantarları suyunu çekene kadar soteleyin.': 'Обжарьте лук и грибы на сливочном масле, пока не испарится жидкость.',
  'Tereyağında unu 1 dakika kavurun, sütü azar azar ekleyerek koyulaştırın.': 'Обжарьте муку на сливочном масле 1 минуту, постепенно влейте молоко и загустите.',
  'Tereyağında unu 1 dakika kavurun, sütü çırparak ekleyip 3 dakika koyulaşana kadar pişirin.': 'Обжарьте муку на масле 1 минуту, влейте молоко, взбивая, и варите 3 минуты до загустения.',
  'Tereyağında unu kavurup sütü azar azar ekleyerek koyulaştırın.': 'Обжарьте муку на масле и загустите, постепенно добавляя молоко.',
  'Tereyağını geniş tencerede eritin; irmik ve fıstığı ekleyip kısık ateşte sürekli karıştırarak 15–18 dakika, açık kahve rengi olana kadar kavurun.': 'Растопите масло в широкой кастрюле; добавьте манку и кедровые орехи и обжаривайте на слабом огне, постоянно помешивая, 15–18 минут до светло-коричневого цвета.',
  'Tereyağını tavada eritip karışımı dökün.': 'Растопите масло на сковороде и вылейте смесь.',
  'Terlik': 'Тапочки',
  'Termos': 'Термос',
  'Test pozitifse doktor randevusu al; folik asidi sürdür.': 'Если тест положительный, запишитесь к врачу; продолжайте фолиевую кислоту.',
