  'Ton balığı, zeytin ve kapariyi ekleyip 2 dakika daha ısıtın; ton balığını çok ezmeden karıştırın.': 'Добавьте тунец, маслины и каперсы и прогрейте ещё 2 минуты; перемешивайте, не разминая тунец.',
  'Top oyunları, basit sıralama (büyük-küçük), oyun hamuru (gözetimli).': 'Игры с мячом, простая сортировка (большой–маленький), пластилин (под присмотром).',
  'Topa ayakla vurmayı dener; kaşık-çatal kullanımı gelişir. Diğer çocuklara ilgi artar ama genellikle yan yana oynar.': 'Пытается пинать мяч; лучше управляется с ложкой и вилкой. Больше интереса к другим детям, но обычно играет рядом с ними.',
