  'Trafik, oyun alanı, su güvenliği ve yabancılarla sınırlar konusunda yaşa uygun konuşun. Bisiklet ve benzeri etkinliklerde uygun koruyucu ekipman kullanın.': 'По возрасту обсуждайте дорогу, детские площадки, безопасность на воде и границы с незнакомцами. Используйте защиту при катании на велосипеде и подобных занятиях.',
