  'Tutarlı bir akşam rutini oluşturun. Gündüz uykusu ve gece uykusundaki değişimleri gözlemleyin; tek bir saat hedefini zorlamayın.': 'Создайте постоянный вечерний ритуал. Следите за изменениями дневного и ночного сна; не навязывайте единственное «правильное» время.',
  'Tutarlı kurallar çocuğun kendini güvende hissetmesine yardımcı olur.': 'Последовательные правила дают ребёнку ощущение безопасности.',
  'Tutunarak yürür; kısa süre tek başına ayakta durabilir. İşaret ederek ister, basit yönergeleri anlamaya başlar.': 'Ходит за руку; может недолго стоять сам. Показывает пальцем, чтобы попросить, начинает понимать простые просьбы.',
  'Tuvalet eğitimi': 'Приучение к горшку',
  'Tuvalet eğitimine yaş değil hazırlık belirtileri yön verir; çoğu çocuk 2–3 yaş arasında hazır olur.': 'Приучение к горшку определяют признаки готовности, а не возраст; большинство детей готовы в 2–3 года.',
  'Tuvalet kâğıdı': 'Туалетная бумага',
  'Tuvalet sonrası önden arkaya temizlen; ilişki sonrası idrara çık.': 'После туалета подмывайтесь спереди назад; мочитесь после полового акта.',
  'Tuvalet sonrası önden arkaya ılık suyla temizle, kurula.': 'После туалета подмывайтесь тёплой водой спереди назад и промокайте.',
