  'Tuz eklemeyin; çeşitlilik için farklı tahıllarla dönüşümlü sunun.': 'Не солите; для разнообразия чередуйте с другими крупами.',
  'Tuz için günlük üst sınır yetişkinlerde yaklaşık 5 g\'dır (bir çay kaşığı).': 'Суточный предел соли для взрослых — около 5 г (чайная ложка).',
