  'Yetişkin kadınlar için günlük toplam sıvı ihtiyacı yaklaşık 2–2,5 litredir; sıcak havada, gebelikte ve emzirmede artar.': 'Взрослым женщинам нужно в сумме около 2–2,5 л жидкости в день; больше в жару, при беременности и кормлении.',
  'Yetişkin kontrollü su': 'Вода под контролем взрослого',
