  'Yüklenen referanslar yalnızca bu ekran açıkken tutulur. 0–24 ay aylık WHO persentilleri bilgi amaçlıdır; tıbbi değerlendirme değildir.': 'Загруженные нормы хранятся, только пока открыт этот экран. Месячные процентили ВОЗ для 0–24 месяцев носят информационный характер; это не медицинская оценка.',
  'Yüksek ateş, aşırı halsizlik veya uyandırmakta güçlük.': 'Высокая температура, сильная слабость или малыша трудно разбудить.',
  'Yüksek ateş, nefes darlığı, bayılma, nöbet: 112.': 'Высокая температура, одышка, обморок, судороги: звоните по местному номеру экстренной помощи.',
  'Yüksek sarılık değerleri tedavi edilmezse zarar verebilir; bu nedenle kontrol önemlidir.': 'Очень высокий уровень билирубина без лечения может быть опасен, поэтому осмотры важны.',
  'Yüksek yüzeylerde yalnız bırakmayın. Küçük parçaları, kabloları, ilaçları ve sıcak içecekleri erişimden uzak tutun; uygun oto koltuğu kullanın.': 'Не оставляйте одного на возвышении. Держите мелкие детали, провода, лекарства и горячие напитки вне досягаемости; используйте подходящее автокресло.',
  'Yüksek ısı ve tek kat dizmek karnabaharın haşlanmak yerine kavrulmasını sağlar.': 'Высокая температура и один слой позволяют капусте запекаться, а не тушиться.',
  'Yüksek, yüce': 'Высокий, возвышенный',
  'Yüksekten düşme, bilinç değişikliği veya kusma.': 'Падение с высоты, изменение сознания или рвота.',
  'Yükseliş': 'Восхождение',
  'Yükseliş; merdiven': 'Восхождение; лестница',
  'Yükselme, terakki': 'Возвышение, прогресс',
  'Yükselmek': 'Возвышаться',
  'Yürüme için güvenli alan, basit şekil yerleştirme, birlikte şarkı ve kitap. 1 yaş kontrolüne git.': 'Безопасное пространство для ходьбы, простые сортеры, песни и книжки вместе. Сходите на осмотр в 1 год.',
  'Yürüme, ilk kelimeler ve bağımsızlık isteği bu dönemin öne çıkan özellikleridir.': 'Ходьба, первые слова и стремление к самостоятельности — главное на этом этапе.',
  'Yürüteç kullanma: düşme ve yaralanma riskini artırır.': 'Не используйте ходунки: они повышают риск падений и травм.',
  'Yürüyüş, yüzme, sabit bisiklet ve gebe yogası güvenli seçeneklerdir.': 'Ходьба, плавание, велотренажёр и йога для беременных — безопасный выбор.',
  'Yürüyüşle başlayıp yavaş yavaş artır.': 'Начните с прогулок и увеличивайте нагрузку постепенно.',
  'Yüz ifadeleri başlayabilir; vücudu ince tüylerle (lanugo) kaplanmaya başlar.': 'Может появиться мимика; тело начинает покрываться пушковыми волосами (лануго).',
  'Yüz ifadelerini keşfet': 'Изучаем мимику',
  'Yüz temizliği, nemlendirme ve güneşten korunmayı üç kısa adıma bölün. Yeni ürünleri tek tek ekleyerek cildinizin tepkisini gözlemleyin.': 'Разделите очищение, увлажнение и защиту от солнца на три коротких шага. Добавляйте новые средства по одному и наблюдайте за реакцией кожи.',
  'Yüz ve ellerde ani şişlik, nefes darlığı: hemen başvur.': 'Внезапный отёк лица и рук, одышка: немедленно обратитесь за помощью.',
  'Yüz-dil şişmesi, solunum güçlüğü veya baygınlık gibi bulgular acil değerlendirme gerektirir.': 'Признаки вроде отёка лица или языка, затруднённого дыхания или обморока требуют неотложной оценки.',
  'Yüzey temizleyici': 'Средство для поверхностей',
  'Yüzeyine streç değdirerek buzdolabında 1 gün.': '1 день в холодильнике, плёнка вплотную к поверхности.',
  'Yıkama talimatı': 'Инструкция по стирке',
  'Yıkama ve ütü talimatlarını kontrol edin. Hassas kumaşları uygun programda yıkayın; kurutma talimatlarına uyun.': 'Проверьте инструкции по стирке и глажке. Деликатные ткани стирайте в подходящем режиме; соблюдайте указания по сушке.',
  'Yıkanabilirlik': 'Можно стирать',
  'Yıkanmış bulguru ekleyip 1 dakika karıştırın.': 'Добавьте промытый булгур и помешайте 1 минуту.',
  'Yıkanmış karabuğdayı ve sıcak suyu ilave edin.': 'Добавьте промытую гречку и горячую воду.',
  'Yıkanmış pirinci ve suyu ilave edin.': 'Добавьте промытый рис и воду.',
  'Yıkanmış pirinç, portakal suyu ve suyu ekleyin.': 'Добавьте промытый рис, апельсиновый сок и воду.',
  'Yıkanmış ıspanağı ekleyip söndürün.': 'Добавьте промытый шпинат и дайте ему опасть.',
  'Yıkayıp soyun.': 'Вымойте и очистите.',
  'Yılan yavrusu; Osman Gazi': 'Змеёныш; Осман Гази',
  'Yılda 2–3\'ten fazla tekrarlayan enfeksiyon.': 'Более 2–3 повторных инфекций в год.',
  'Yılda bir genel kontrol; doktorunun önerisine göre.': 'Общий осмотр раз в год; по рекомендации врача.',
  'Yılda bir; büyüyen, renk değiştiren ya da kanayan ben için beklemeden.': 'Раз в год; если родинка растёт, меняет цвет или кровоточит — не ждите.',
